  ["records", "tail -n 20 records/experiments.jsonl", 30000]
];
const rs = await Promise.all(cmds.map(async ([label, cmd, max_output_tokens]) => {
  const x = await tools.exec_command({cmd, workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project", yield_time_ms:10000, max_output_tokens});
  return `===== ${label} =====\n${x.output}`;
}));
rs.forEach(text);

const cmds = [
  "sed -n '120,420p' candidates/classical_probe.py",
  "sed -n '1,260p' CANDIDATES.md",
  "sed -n '1,220p' input/competition/README.md",
  "ps -eo pid,etime,cmd --sort=-etime | rg 'python|pair|probe' | head -40"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000})));
